  ecoRecover.addEventListener('click',()=>{const id=ecoRecovery.value;resetEco();run('environmental_state',{review_id:id},r=>{if(r.review_id!==id||r.confirmations_restored!==false||r.ledger_written!==false||!r.preview?.assessment)throw Error('Recuperación ambiental incompatible.');const corrections=r.corrections;if(corrections&&(!r.applied||corrections.observation_id!==r.applied.observation_id||!Number.isInteger(corrections.revision)||corrections.revision<0||corrections.revision>100||!corrections.effective_assessment))throw Error('Historia de correcciones incompatible.');const effective=corrections?.effective_assessment??r.preview.assessment;showEco(effective);const snap=effective.snapshot,single=snap.activities.length===1&&snap.factors.length===1;if(single){const a=snap.activities[0],f=snap.factors[0];for(const [input,value] of [[ecoOperation,a.source_reference??''],[ecoSegment,a.source_segment??''],[ecoId,a.id],[ecoDay,a.date],[ecoQuantity,a.quantity],[ecoUnit,a.unit],[ecoPassengers,a.passengers??''],[ecoFactor,f.id],[ecoVersion,f.version],[ecoRate,f.kg_co2e_per_unit],[ecoFrom,f.valid_from],[ecoUntil,f.valid_until],[ecoGeography,f.geography],[ecoBoundary,f.boundary],[ecoEvidence,f.source_digest],[ecoSupport,corrections?.revision>0?'':r.preview.evidence_digest]])input.value=String(value);}ecoReview=r.reviewed_by_current_owner&&single?{review_id:id,preview:r.preview}:null;ecoApplied=Boolean(r.applied);ecoPreview.textContent=r.applied?'Medición confirmada: '+r.applied.observation_id+' · Conocida desde '+r.applied.known_at+(corrections?.revision>0?' · Corrección vigente '+corrections.revision+'. Original conservado; el total corregido sustituye al original.':''):'Revisión recuperada; la segunda confirmación debe darse nuevamente.';status.textContent='Estado ambiental recuperado; no se restauraron autorizaciones.';});});
