  async function localDraft(action){if(!company||!window.SGACDOfflineDrafts)return;const task=++epoch,scope=company,id=offlineId.value,password=offlinePassword.value,new_password=offlineNewPassword.value;offlinePassword.value=offlineNewPassword.value='';pending?.abort();let completedEpoch=task;busy=true;controls();status.textContent='Procesando borrador cifrado en este navegador…';try{const args={company_id:scope,draft_id:id,password,expected_revision:offlineRevision};let result;if(action==='save')result=await window.SGACDOfflineDrafts.save({...args,value:{kind:'environmental_draft',...ecoPayload(),evidence_digest:ecoSupport.value}});else if(action==='load')result=await window.SGACDOfflineDrafts.load(args);else if(action==='rotate')result=await window.SGACDOfflineDrafts.rotate({...args,new_password});else if(action==='backup')result=await window.SGACDOfflineDrafts.backup(args);else{const file=offlineFile.files?.[0];if(!file||file.size>15000)throw Error('Selecciona una copia cifrada de hasta 15000 bytes.');result=await window.SGACDOfflineDrafts.restore({...args,archive:JSON.parse(await file.text())});}if(disposed||task!==epoch||document.hidden||company!==scope)return;if(result.uploaded!==false||result.authorizations_restored!==false)throw Error('Estado local incompatible.');offlineRevision=result.revision;offlineRevisionText.textContent='Versión local: '+offlineRevision;if(action==='load'||action==='restore'){resetEco();completedEpoch=epoch;const a=result.value.activities[0],f=result.value.factors[0];for(const [input,value] of [[ecoOperation,a.source_reference??''],[ecoSegment,a.source_segment??''],[ecoId,a.id],[ecoDay,a.date],[ecoQuantity,a.quantity],[ecoUnit,a.unit],[ecoPassengers,a.passengers??''],[ecoFactor,f.id],[ecoVersion,f.version],[ecoRate,f.kg_co2e_per_unit],[ecoFrom,f.valid_from],[ecoUntil,f.valid_until],[ecoGeography,f.geography],[ecoBoundary,f.boundary],[ecoEvidence,f.source_digest],[ecoSupport,result.value.evidence_digest]])input.value=String(value);status.textContent=action==='restore'?'Copia cifrada restaurada como borrador; no se restauraron autorizaciones.':'Borrador local recuperado. Reconecta y revisa de nuevo; no se restauraron autorizaciones.';}else if(action==='backup'){const url=URL.createObjectURL(new Blob([JSON.stringify(result.archive)],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download='sgacd-draft-'+id+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status.textContent='Copia cifrada exportada; conserva su identificador y contraseña.';}else status.textContent=action==='save'?'Borrador cifrado guardado solo en este navegador.':'Contraseña local actualizada; se conservó el contenido del borrador.';}catch(error){if(!disposed&&task===epoch)status.textContent=error instanceof Error?error.message:'No se pudo procesar el borrador local.';}finally{if(!disposed&&completedEpoch===epoch){busy=false;controls();}}}
